import { memo, useEffect, useState } from 'react';
import { FlatList, Text, View } from 'react-native';
import { useHikes } from '../state/hikes';

const HikeRow = memo(function HikeRow({ hike }) {
  return (
    <View style={{ padding: 12 }}>
      <Text>{hike.name}</Text>
      <Text>{hike.distanceKm} km</Text>
    </View>
  );
});

export default function HikeLog() {
  const hikes = useHikes();
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 16);
    return () => clearInterval(id);
  }, []);

  return (
    <View style={{ flex: 1 }}>
      <Text>Updated {new Date(now).toLocaleTimeString()}</Text>
      <FlatList
        data={hikes}
        keyExtractor={(item, index) => String(index)}
        renderItem={({ item }) => <HikeRow hike={{ ...item }} />}
      />
    </View>
  );
}
